// Plug value index — record JAH-GPCS-SMARTPLUG-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"max_w": 1800, "price_usd": 15};
var value = (m.max_w/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GPCS-SMARTPLUG-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GPCS-SMARTPLUG-000001|' + value.toFixed(2) + ' value index');

